const circuitSources = {"margin-left.svg":"data:image/svg+xml;base64,","margin-right.svg":"data:image/svg+xml;base64,"};
// Quiet margin automata: finer cells, randomised re-seeding, mixed rules,
// and circuit-influenced evolution.
(() => {
  const mobile = matchMedia('(max-width:900px)');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const strips = [...document.querySelectorAll('.circuit-margin')];
  const pixel = 0.75, interval = 80;
  const availableRules = [22, 30, 45, 54, 90, 110, 122, 126, 150];
  const ruleBit = (rule, left, mid, right) => (rule >> ((left<<2) | (mid<<1) | right)) & 1;
  const rand = n => Math.floor(Math.random() * n);
  const choice = arr => arr[rand(arr.length)];
  const clamp = (v,a,b) => Math.max(a, Math.min(b, v));

  function parseBgUrl(str){
    const m = /url\(["']?(.+?)["']?\)/.exec(str || '');
    return m ? m[1] : '';
  }
  function parsePos(token, freeSpace){
    token = (token || '50%').trim();
    if (token === 'left' || token === 'top') return 0;
    if (token === 'center') return freeSpace / 2;
    if (token === 'right' || token === 'bottom') return freeSpace;
    if (token.endsWith('%')) return freeSpace * parseFloat(token) / 100;
    const px = parseFloat(token);
    return Number.isFinite(px) ? px : freeSpace / 2;
  }

  const fields = strips.map((strip,i) => {
    const canvas = document.createElement('canvas');
    canvas.className='circuit-automaton';
    canvas.setAttribute('aria-hidden','true');
    strip.append(canvas);
    const f = {strip, canvas, ctx:canvas.getContext('2d'), i, visible:false, patches:[], mask:null, img:null, imgReady:false};
    if (!f.ctx) return null;
    const url = parseBgUrl(getComputedStyle(strip).backgroundImage);
    if (url) {
      f.img = new Image();
      f.img.decoding = 'async';
      f.img.onload = () => { f.imgReady = true; resize(f); };
      f.img.src = circuitSources[url.split('/').pop()] || url;
    }
    return f;
  }).filter(Boolean);

  function buildMask(f){
    const w = f.canvas.width, h = f.canvas.height;
    f.mask = new Uint8Array(w * h);
    f.maskReady=false;
    if (!f.imgReady || !f.img || !f.img.naturalWidth || !f.img.naturalHeight) return;
    const temp = document.createElement('canvas');
    temp.width = w; temp.height = h;
    const tctx = temp.getContext('2d');
    if (!tctx) return;
    tctx.clearRect(0,0,w,h);

    // Approximate the CSS background placement used for the margin drawings.
    const size=getComputedStyle(f.strip).backgroundSize;
    const drawH = f.strip.closest('.folio-four') ? Math.max(h,480*h/Math.max(1,f.strip.clientHeight)) : h;
    const drawW = f.img.naturalWidth * (drawH / f.img.naturalHeight);
    const pos = (getComputedStyle(f.strip).backgroundPosition || 'center center').split(/\s+/);
    const x = parsePos(pos[0], w - drawW);
    const y = parsePos(pos[1] || 'center', h - drawH);
    tctx.drawImage(f.img, x, y, drawW, drawH);
    let data;
    try { data=tctx.getImageData(0,0,w,h).data; } catch(e) { return; }
    for(let i=0;i<w*h;i++){
      const a = data[i*4+3];
      const lum = (data[i*4] + data[i*4+1] + data[i*4+2]) / 3;
      f.mask[i] = (a/255 * (255-lum) > 12) ? 1 : 0;
    }
    f.maskReady=f.mask.some(bit=>bit===1);
  }
  function maskAt(f,x,y){
    x = x|0; y = y|0;
    if (!f.mask || x < 0 || y < 0 || x >= f.canvas.width || y >= f.canvas.height) return 0;
    return f.mask[y * f.canvas.width + x];
  }
  // One full-strip automaton, with a new rule on every downward sweep.
  function restart(f){
    const w=f.canvas.width;
    f.rule=choice(availableRules.filter(r=>r!==f.rule));
    f.altRule=choice(availableRules.filter(r=>r!==f.rule));
    f.row=Uint8Array.from({length:w},(_,x)=>maskAt(f,x,f.strip.closest('.folio-two')?f.canvas.height-1:0) ^ Number(Math.random()<.025));
    f.restoring=false;
    f.y=0;
  }
  function resize(f){
    if(mobile.matches)return;
    const w=f.strip.clientWidth,h=f.strip.clientHeight;
    f.canvas.width=Math.max(1,Math.ceil(w/pixel));
    f.canvas.height=Math.max(1,Math.ceil(h/pixel));
    buildMask(f);restart(f);
  }
  const observer=new IntersectionObserver(entries=>{for(const e of entries){const f=fields.find(f=>f.strip===e.target);if(f)f.visible=e.isIntersecting;}});
  const ro=new ResizeObserver(entries=>{for(const e of entries){const f=fields.find(f=>f.strip===e.target);if(f)resize(f);}});
  for(const f of fields){resize(f);observer.observe(f.strip);ro.observe(f.strip);}
  function draw(){
    if(document.hidden||reduced.matches||mobile.matches)return;
    for(const f of fields){
      if(!f.visible || !f.maskReady)continue;
      const {ctx,canvas}=f,w=canvas.width,h=canvas.height;
      // Complete each sweep in approximately 12 seconds, regardless of folio height.
      const batch=Math.max(1,Math.ceil(h/150));
      for(let j=0;j<batch;j++){
        if(f.restoring){
          if(f.y<=0){restart(f);continue;}
          --f.y;ctx.clearRect(0,f.strip.closest('.folio-two')?h-1-f.y:f.y,w,1);
          continue;
        }
        if(f.y>=h){f.restoring=true;continue;}
        const y=f.y, flipped=!!f.strip.closest('.folio-two');
        const yy=flipped?h-1-y:y;
        // Circuit ink is a binary input to every generation, not a separate overlay.
        const input=Uint8Array.from(f.row,(bit,x)=>bit | maskAt(f,x,yy));
        const next=new Uint8Array(w);
        ctx.fillStyle='#fff';ctx.fillRect(0,yy,w,1);
        ctx.fillStyle='#c2c2c2';
        for(let x=0;x<w;x++){
          next[x]=ruleBit(f.rule,input[x-1]||0,input[x],input[x+1]||0);
          if(next[x])ctx.fillRect(x,yy,1,1);
        }
        f.row=next;f.y++;

      }
    }
  }
  setInterval(draw,interval);
})();
